        return None
    if m := re_year.search(date):
        return m.group(1)
    return None


def dates_are_exact(author: dict, candidate: dict) -> bool:
    """
    Whether both birth and death years of author and candidate are known and
    equal. Only the year component of the dates is compared.

    :param dict author: Author import dict
    :param dict candidate: OL author record
    :rtype: bool
    """
    for field in ('birth_date', 'death_date'):
        wanted = year_of(author.get(field))
        existing = year_of(candidate.get(field))
        if not wanted or existing != wanted:
            return False
    return True


def names_match(pattern: str, name: str) -> bool:
    """
    Case-insensitive match of a name against a pattern which may contain the
    multi-character wildcard "*", mirroring the ILIKE matching of the database.

    :param str pattern: e.g. "John*"
    :param str name: e.g. "Johnson, Jane"
    :rtype: bool
    """
    regex = re.escape(pattern).replace(r'\*', '.*')
    return bool(re.fullmatch(regex, name, flags=re.IGNORECASE))


def get_surname(name: str) -> str:
    """
    Returns the surname of a name, e.g. "Smith" for "John Smith" or for
    "Smith, John".

    :param str name: Author name
    :rtype: str
    """
    name = name.strip().rstrip('.')
    if ',' in name:
        return name.split(',')[0].strip()
    parts = name.split()
    return parts[-1] if parts else name


