import web

from openlibrary.catalog.add_book import load_book
from openlibrary.catalog.add_book.load_book import (
    find_author,
    find_entity,
    get_surname,
    import_author,
)
from openlibrary.mocks.mock_infobase import mock_site  # noqa: F401 (fixture)


def save_author(mock_site, key, name, birth_date=None, death_date=None, alt=None):
    author = {
        'key': key,
        'type': {'key': '/type/author'},
        'name': name,
    }
    if birth_date:
        author['birth_date'] = birth_date
    if death_date:
        author['death_date'] = death_date
    if alt:
        author['alternate_names'] = alt
    mock_site.save(author)


def test_regex_ilike(mock_site):
    assert mock_site.regex_ilike('John*', 'john smith')
    assert mock_site.regex_ilike('john', 'John')
    assert not mock_site.regex_ilike('john', 'John Smith')
    assert mock_site.regex_ilike('*, Smith', 'Smith') is False
    assert mock_site.regex_ilike('Sm_th', 'Smith') is False  # '_' not a wildcard
    assert mock_site.regex_ilike('Sm_th', 'Sm_th')


def test_case_insensitive_name_match(mock_site):
    save_author(mock_site, '/a/OL1A', 'Mark Twain')
    assert find_entity({'name': 'MARK TWAIN'})['key'] == '/a/OL1A'
    assert find_entity({'name': 'mark twain'})['key'] == '/a/OL1A'


def test_no_dates_falls_back_to_name(mock_site):
    save_author(mock_site, '/a/OL1A', 'Mark Twain', birth_date='1835')
    # death_date absent in input -> name-only match
    assert find_entity({'name': 'Mark Twain', 'birth_date': '1835'})['key'] == '/a/OL1A'
    assert find_entity({'name': 'Mark Twain'})['key'] == '/a/OL1A'


def test_both_dates_exact_take_precedence(mock_site):
    save_author(mock_site, '/a/OL2A', 'John Smith', birth_date='1900')
    save_author(mock_site, '/a/OL3A', 'John Smith', birth_date='1950', death_date='2000')
    got = find_entity(
        {'name': 'John Smith', 'birth_date': '1950', 'death_date': '2000'}
    )
    assert got['key'] == '/a/OL3A'


def test_wildcard_returns_first_by_numeric_key(mock_site):
    save_author(mock_site, '/a/OL10A', 'John*able')
    save_author(mock_site, '/a/OL2A', 'Johnson, Jane')
    got = find_entity({'name': 'John*'})
    assert got['key'] == '/a/OL2A'
    assert len(find_author({'name': 'John*'})) == 2


def test_no_match_returns_new_candidate(mock_site):
    save_author(mock_site, '/a/OL1A', 'Mark Twain', birth_date='1835', death_date='1910')
    assert find_entity({'name': 'Nobody At All'}) is None
    new = import_author(
        {'name': 'Nobody At All', 'birth_date': '1835', 'death_date': '1910'}
    )
    assert new == {
        'name': 'Nobody At All',
        'birth_date': '1835',
        'death_date': '1910',
        'type': {'key': '/type/author'},
    }
    # The '*' is preserved in the name of a new candidate.
    new = import_author({'name': 'John*'})
    assert new['name'] == 'John*'


def test_alternate_names_match(mock_site):
    save_author(
        mock_site,
        '/a/OL5A',
        'Mark Twain',
        birth_date='1835',
        death_date='1910',
        alt=['Samuel Langhorne Clemens'],
    )
    author = {
        'name': 'Samuel Langhorne Clemens',
        'birth_date': '1835',
        'death_date': '1910',
    }
    assert find_entity(author)['key'] == '/a/OL5A'
    # Mismatched dates invalidate the alternate_names match.
    assert (
        find_entity({**author, 'birth_date': '1836'})
        is None
    )
    # Both dates must be present in the input.
    assert find_entity({'name': 'Samuel Langhorne Clemens', 'birth_date': '1835'}) is None


def test_surname_match(mock_site):
    save_author(
        mock_site, '/a/OL7A', 'Twain, Mark', birth_date='b. 1835', death_date='d. 1910'
    )
    author = {'name': 'Mark Twain', 'birth_date': '1835', 'death_date': '1910'}
    assert find_entity(author)['key'] == '/a/OL7A'
    # mismatched year -> no surname match
    assert find_entity({**author, 'death_date': '1911'}) is None
    # missing death date in input -> no surname match (no name match either)
    assert find_entity({'name': 'Mark Twain', 'birth_date': '1835'}) is None
    # candidate missing a date -> not an exact match
    save_author(mock_site, '/a/OL8A', 'Doyle, Arthur Conan', birth_date='1859')
    assert (
        find_entity(
            {'name': 'Arthur Conan Doyle', 'birth_date': '1859', 'death_date': '1930'}
        )['key']
        == '/a/OL8A'
    )  # falls back to compatible name match


def test_get_surname():
    assert get_surname('Smith, John') == 'Smith'
    assert get_surname('John Smith') == 'Smith'
    assert get_surname('John Smith.') == 'Smith'


def test_find_author_returns_list(mock_site):
    save_author(mock_site, '/a/OL1A', 'Mark Twain')
    assert isinstance(find_author({'name': 'Mark Twain'}), list)
    assert isinstance(find_author({'name': 'Not Found'}), list)
    assert find_author({'name': 'Not Found'}) == []


def test_redirected_author(mock_site):
    mock_site.save(
        {
            'key': '/a/OL2A',
            'type': {'key': '/type/redirect'},
            'location': '/a/OL3A',
        }
    )
    save_author(mock_site, '/a/OL3A', 'Mark Twain')
    assert find_entity({'name': 'Mark Twain'})['key'] == '/a/OL3A'
"}

